"""Append measured interim evidence without changing the active scientific plan."""
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from research_identity_assignment_run_20261108.common import *


def main():
    report=read(RUN/'comparison_report.json');assert read(RUN/'independent_audit.json')['passed']
    paired=read(RUN/'gemini_paired_review.json');assert paired['passed']
    stamp=datetime.now(MSK).strftime('%d.%m.%Y, %H:%M MSK')
    entry=f'**{stamp}** — Промежуточные результаты исполнения `identity_assignment_v2_run_20261108` и исправление контекста для Gemini.\n\n'
    entry+='*Получено.* Нулевые поправки побитно воспроизвели полный исходный выход и состояния на1204кадрах; восстановленные1585состояний также прошли сверку (`runs/identity_assignment_20261108/zero_parity.json`, `restored_zero_parity.json`). Восстановлены входы и причинные карты47видео; исходный checkpoint не изменён (`input_complete.json`, `features_complete.json`). На641историческом запросе: исходный вариант41правильный/6чужих/594отказа; геометрия63/17/561; геометрия+FlyVis60/15/566. Парные интервалы по видео не подтвердили добавку FlyVis над геометрией (`comparison_report.json`), независимый аудит исходных матриц и исходов прошёл (`independent_audit.json`). Это однокадровая проверка из исходных состояний, не HOTA полного трекера.\n\n'
    entry+='*Механизм.* Среди выигравших первое сопоставление ID в геометрическом варианте4пропали при очистке дубликатов, в варианте FlyVis3; нужная рамка может уже сопровождаться другим фрагментом той же машины. В исходном запросе29017 вариантFlyVis и контрольR1 вернули ID158, геометрия не вернула; запрос29057 остался без возврата во всех выбранных вариантах (`mechanism_report.json`). Нельзя объявлять оба случая решёнными или весь эффект специфичным FlyVis.\n\n'
    entry+='*Четвёртая проблема.* Геометрический аудит различил квадрат входного окна, оболочку центров721колонки и объединённую поддержку13×13входных фильтров. Из178положительных запросов истинная рамка целиком в квадрате139раз, в оболочке102раза, в поддержке112раз (`coverage_followup_recovery1.json`, `coverage_rows.json`). Выход за окно измерен; причинное влияние обрезания на узнавание ещё не проверено.\n\n'
    entry+='*Техническое восстановление.* В первом полном пилоте обнаружено преждевременное приведение Retina кfloat32 доresize; исходный путь с кадра1даётfloat64 и уменьшает изображение до приведения типа. Прежние сигнальные результаты сохранены как предварительные. Отдельная версия `full_precision` восстанавливает исходный тип каждого кадра, хранит вход потоково и сохраняет контрольные точки;9проверок против исходного EyeBank дали точное совпадение (`full_precision/technical_gate.json`). Из196старых карт первого видео переиспользуются только карты, все входы причинной последовательности которых точны;10из379проверенных входных видов различались. Старые остановки контроллера памяти и частичные файлы сохранены. Научные параметры, детекции, ядро, критерии и системный запас памяти не изменены (`full_precision_execution_phase.json`, `full_precision/recovery_registration.json`). Полный пилот20val выполняется последовательной защищённой очередью, результат HOTA пока не готов.\n\n'
    entry+='*Исправление собственного объяснения.* Gemini не видел код; недостаточное описание в запросе — ответственность Codex. Фактическая поправка центрируется по всем претендентам, включая рассматриваемого, а не только по остальным. По сохранённымUID переход от геометрии кFlyVis отменил7назначений(4правильных,3чужих) и добавил2(1правильное,1чужое), а не просто отменил5. Подготовлен самодостаточный исправленный контекст с кодом, парными исходами и ограничениями (`gemini_paired_review.json`, `gemini_context_corrected.json`). Предложения Gemini о слиянии состояний, изменении очистки и новом входном окне не запускались.\n\n'
    entry+='*Решение.* Досчитать уже разрешённый полный пилот с прежними контролями и ограничениями вреда. Не выдавать условный прирост, исправность реализации или геометрическое покрытие за решение всех четырёх проблем. Очередь действующего плана и защищённые гипотезы не менялись.\n\n'
    path=RUN/'interim_journal.json';write(path,dict(entry=entry),new=True)
    plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md';text=plan.read_text(encoding='utf-8');anchor='## Журнал изменений\n\n';assert text.count(anchor)==1
    plan.write_text(text.replace(anchor,anchor+entry,1),encoding='utf-8')


if __name__=='__main__':main()
